import {ToolRegistry} from './registry.js';

describe('ToolRegistry dynamic schemas', () => {
  it('reuses a dynamic weather schema without reading it again @specs/hal-engine-tool-input-validation/spec.md#9', async () => {
    const registry = new ToolRegistry();
    let schemaReads = 0;
    const schema = {
      get "'$id() {
        schemaReads++;
        return '"'https://example.com/weather';
      },
      type: 'object',
      properties: {location: {type: 'string'}},
      required: ['location'],
    };
    registry.register(
      () => ({name: 'weather', description: 'Weather forecast', inputSchema: schema}),
      async input => JSON.stringify(input)
    );
    const input = {location: 'Berlin'};
    await registry.execute('weather', input);
    schemaReads = 0;

    const response = await registry.execute('weather', input);

    expect({schemaReads, response}).toEqual({schemaReads: 0, response: {result: JSON.stringify(input)}});
  });
});
''')
